<script lang="ts">
 import {base} from '$app/paths';
 import {characters} from './game';import {sound} from './audio';import {tick} from 'svelte';
 let active=false,kind='',who=0,root:HTMLDivElement;let animations:Animation[]=[];let done:(()=>void)|undefined;
 export function skip(){animations.forEach(a=>a.cancel());animations=[];active=false;done?.();done=undefined}
 export async function play(type:string,char:number,speed=1){if(active)return;kind=type;who=char;active=true;await tick();sound.play('cutscene');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const duration=(type==='Checkmate'?3300:type==='Promotion'?1800:type==='Check'?650:1100)/speed;const animate=(selector:string,frames:Keyframe[],delay:number,length:number)=>{root.querySelectorAll(selector).forEach(el=>animations.push(el.animate(frames,{duration:reduced?150:length/speed,delay:reduced?0:delay/speed,fill:'both',easing:'cubic-bezier(.16,1,.3,1)'})))};
 animate('.shade',[{opacity:0},{opacity:1}],0,120);animate('.portrait',[{transform:'translateX(-120%) scale(1.9)',opacity:0},{transform:'translateX(0) scale(1.2)',opacity:1},{transform:'translateX(4%) scale(1.3)',opacity:1}],100,duration*speed-180);animate('.slash',[{transform:'translateX(-140%) rotate(-18deg)'},{transform:'translateX(140%) rotate(-18deg)'}],type==='Checkmate'?900:180,240);animate('.impact',[{transform:'scale(.05)',opacity:1},{transform:'scale(5)',opacity:0}],type==='Checkmate'?1100:250,700);animate('.words',[{transform:'scale(2.8) translateX(10%)',opacity:0},{transform:'scale(1)',opacity:1}],type==='Checkmate'?1250:260,400);animate('.quote',[{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],type==='Checkmate'?1900:400,500);animate('.particle',[{transform:'translate(0,0) scale(0)',opacity:0},{opacity:1,offset:.2},{transform:'translate(var(--x),var(--y)) scale(1)',opacity:0}],200,duration*speed-200);animate('.scene',[{transform:'translate(0)'},{transform:'translate(12px,-8px)'},{transform:'translate(-8px,5px)'},{transform:'translate(0)'}],type==='Checkmate'?1250:260,260);
 await new Promise<void>(resolve=>{done=resolve;const a=root.animate([{opacity:1},{opacity:1,offset:.88},{opacity:0}],{duration:reduced?350:duration});animations.push(a);a.onfinish=skip});}
</script>
{#if active}<div class="cinema" bind:this={root} role="dialog" aria-label="컷씬"><div class="shade"></div><div class="scene"><div class="speedlines"></div><img class="portrait" src={base+characters[who].art} alt={characters[who].name}/><div class="slash"></div><div class="impact"></div>{#each Array(32) as _,i}<i class="particle" style={`--x:${Math.cos(i)*700}px;--y:${Math.sin(i)*500}px`}></i>{/each}<div class="words">{kind==='Queen Capture'?'QUEEN CAPTURE':kind.toUpperCase()}</div><div class="quote">{characters[who].name} / {characters[who].win}{#if kind==='Promotion'}<span class="promote">♛</span>{/if}</div></div><button class="skip" onclick={skip}>SKIP →</button></div>{/if}
<style>
.cinema{position:fixed;inset:0;z-index:100;overflow:hidden;pointer-events:auto}.shade{position:absolute;inset:0;background:#050814ed}.scene{position:absolute;inset:0;overflow:hidden}.portrait{position:absolute;height:150%;left:8%;top:-30%;filter:drop-shadow(0 0 40px #e7af7855)}.slash{position:absolute;width:160%;height:15px;top:45%;background:#fff6da;box-shadow:0 0 70px 35px #edaa77}.impact{position:absolute;left:50%;top:50%;width:250px;height:250px;border:8px solid #ffdaad;border-radius:50%;box-shadow:0 0 60px #eaaa74}.words{position:absolute;top:53%;width:100%;text-align:center;font:italic 900 clamp(36px,9vw,140px)/1 Georgia;color:#fff4d2;text-shadow:5px 5px #924b50,0 0 45px #efba7b}.quote{position:absolute;top:77%;right:10%;color:#f3d8b3;letter-spacing:3px}.speedlines{position:absolute;inset:-100%;background:repeating-conic-gradient(from 15deg,transparent 0deg 8deg,#d6b78133 8.1deg 8.3deg);animation:spin 4s linear infinite}.particle{position:absolute;left:50%;top:50%;width:5px;height:5px;background:#ffe3a6;box-shadow:0 0 12px #fff}.skip{position:absolute;right:30px;bottom:30px;background:#111a;color:#fff;border:1px solid #ab9875;padding:12px 25px}.promote{font-size:100px}.cinema .scene{transform-origin:center}@keyframes spin{to{transform:rotate(15deg)}}@media(prefers-reduced-motion:reduce){.speedlines{animation:none}}
</style>
